  "research_question": "Does the sleep environment modify the risk of sudden unexpected infant death (SUID) for male infants after reaching 44 weeks postconceptional age?",
  "outcome": {
    "variable": {"source_id": "cdc", "name": "UCOD"},
    "definition": "Underlying cause of death classified as Sudden Infant Death Syndrome (ICD-10: R95), Unspecified Cause of Death (R99), or Accidental Suffocation and Strangulation in Bed (W75)"
